namespace sv_1a7723c480004a659df359a368aa36e1.Models;

public record JobApplication(PersonalInfo Personal, WorkHistory Work, List<Reference> References, string CoverLetter);
public record PersonalInfo(string FullName, string Email, string Phone, string Address);
public record WorkHistory(List<WorkEntry> Entries);
public record WorkEntry(string Company, string Title, DateTime StartDate, DateTime? EndDate, string Description);
public record Reference(string Name, string Relationship, string Email, string Phone);

public interface IApplicationService
{
    Task<int> SubmitApplicationAsync(JobApplication application);
    Task<bool> ValidateEmailAsync(string email);
}

@namespace sv_1a7723c480004a659df359a368aa36e1.Components.Pages.Apply

<nav class="step-indicator" aria-label="Application progress">
    <ol class="step-list">
        @for (int i = 0; i < StepNames.Count; i++)
        {
            var stepIndex = i;
            var isCompleted = CompletedSteps.Contains(stepIndex);
            var isCurrent = stepIndex == CurrentStep;
            var cssClass = isCurrent ? "step current" : isCompleted ? "step completed" : "step future";

            <li class="@cssClass">
                @if (isCompleted)
                {
                    <button class="step-button" @onclick="() => OnStepSelected.InvokeAsync(stepIndex)">
                        <span class="step-icon">&#10003;</span>
                        <span class="step-label">@StepNames[stepIndex]</span>
                    </button>
                }
                else
                {
                    <span class="step-button" aria-current="@(isCurrent ? "step" : null)">
                        <span class="step-icon">@(stepIndex + 1)</span>
                        <span class="step-label">@StepNames[stepIndex]</span>
                    </span>
                }
            </li>
        }
    </ol>
</nav>

<style>
    .step-indicator {
        margin-bottom: 2rem;
    }

    .step-list {
        display: flex;
        list-style: none;
        padding: 0;
        margin: 0;
        justify-content: space-between;
    }

    .step {
        flex: 1;
        text-align: center;
        position: relative;
    }

    .step-button {
        display: flex;
        flex-direction: column;
        align-items: center;
        gap: 0.5rem;
        background: none;
        border: none;
        cursor: default;
        padding: 0.5rem;
        width: 100%;
    }

    .step.completed .step-button {
        cursor: pointer;
        color: #16a34a;
    }

    .step.completed .step-button:hover {
        text-decoration: underline;
    }

    .step-icon {
        display: flex;
        align-items: center;
        justify-content: center;
        width: 2rem;
        height: 2rem;
        border-radius: 50%;
        font-weight: bold;
        font-size: 0.875rem;
    }

    .step.current .step-icon {
        background-color: #2563eb;
        color: white;
    }

    .step.completed .step-icon {
        background-color: #16a34a;
        color: white;
    }

    .step.future .step-icon {
        background-color: #e5e7eb;
        color: #9ca3af;
    }

    .step-label {
        font-size: 0.75rem;
        font-weight: 500;
    }

    .step.future .step-label {
        color: #9ca3af;
    }

    .step.current .step-label {
        color: #2563eb;
        font-weight: 700;
    }
</style>

@code {
    [Parameter, EditorRequired] public int CurrentStep { get; set; }
    [Parameter, EditorRequired] public HashSet<int> CompletedSteps { get; set; } = new();
    [Parameter, EditorRequired] public EventCallback<int> OnStepSelected { get; set; }

    private static readonly List<string> StepNames = new()
    {
        "Personal Info",
        "Work History",
        "References",
        "Cover Letter",
        "Review & Submit"
    };
}

@namespace sv_1a7723c480004a659df359a368aa36e1.Components.Pages.Apply

<fieldset class="work-entry-fieldset">
    <legend>Position @(Index + 1)</legend>

    <div class="form-row">
        <div class="form-group">
            <label>Company Name *</label>
            <input type="text" value="@Entry.Company"
                   @onchange="e => UpdateEntry(Entry with { Company = (string?)e.Value ?? string.Empty })" />
        </div>
        <div class="form-group">
            <label>Job Title *</label>
            <input type="text" value="@Entry.Title"
                   @onchange="e => UpdateEntry(Entry with { Title = (string?)e.Value ?? string.Empty })" />
        </div>
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Start Date *</label>
            <input type="date" value="@Entry.StartDate.ToString("yyyy-MM-dd")"
                   @onchange="e => UpdateEntry(Entry with { StartDate = DateTime.Parse((string?)e.Value ?? string.Empty) })" />
        </div>
        <div class="form-group">
            <label>End Date</label>
            <input type="date" value="@Entry.EndDate?.ToString("yyyy-MM-dd")" disabled="@IsCurrent"
                   @onchange="e => UpdateEntry(Entry with { EndDate = string.IsNullOrEmpty((string?)e.Value) ? null : DateTime.Parse((string)e.Value) })" />
            <label class="checkbox-label">
                <input type="checkbox" checked="@IsCurrent"
                       @onchange="e => ToggleCurrent((bool)e.Value!)" />
                Currently working here
            </label>
        </div>
    </div>

    <div class="form-group">
        <label>Description</label>
        <textarea rows="3" value="@Entry.Description"
                  @onchange="e => UpdateEntry(Entry with { Description = (string?)e.Value ?? string.Empty })"></textarea>
    </div>

    @if (CanRemove)
    {
        <button type="button" class="btn-remove" @onclick="OnRemove">Remove</button>
    }
</fieldset>

<style>
    .work-entry-fieldset {
        border: 1px solid #e5e7eb;
        border-radius: 0.5rem;
        padding: 1rem;
        margin-bottom: 1rem;
    }

    .work-entry-fieldset legend {
        font-weight: 600;
        padding: 0 0.5rem;
    }

    .checkbox-label {
        display: inline-flex;
        align-items: center;
        gap: 0.5rem;
        margin-top: 0.5rem;
        font-size: 0.875rem;
    }

    .btn-remove {
        background-color: #dc2626;
        color: white;
        border: none;
        padding: 0.4rem 0.8rem;
        border-radius: 0.25rem;
        cursor: pointer;
        font-size: 0.8rem;
    }
</style>

@code {
    [Parameter, EditorRequired] public WorkEntryModel Entry { get; set; } = default!;
    [Parameter] public int Index { get; set; }
    [Parameter] public bool CanRemove { get; set; }
    [Parameter] public EventCallback<WorkEntryModel> OnEntryChanged { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }

    private bool IsCurrent => Entry.IsCurrent;

    private void UpdateEntry(WorkEntryModel updated)
    {
        OnEntryChanged.InvokeAsync(updated);
    }

    private void ToggleCurrent(bool isCurrent)
    {
        var updated = Entry with { IsCurrent = isCurrent, EndDate = isCurrent ? null : Entry.EndDate };
        OnEntryChanged.InvokeAsync(updated);
    }
}

namespace sv_1a7723c480004a659df359a368aa36e1.Components.Pages.Apply;

/// <summary>Mutable model for a work entry during editing.</summary>
public record WorkEntryModel
{
    public string Company { get; init; } = string.Empty;
    public string Title { get; init; } = string.Empty;
    public DateTime StartDate { get; init; } = DateTime.Today;
    public DateTime? EndDate { get; init; }
    public bool IsCurrent { get; init; }
    public string Description { get; init; } = string.Empty;
}

/// <summary>Mutable model for a reference during editing.</summary>
public record ReferenceModel
{
    public string Name { get; init; } = string.Empty;
    public string Relationship { get; init; } = string.Empty;
    public string Email { get; init; } = string.Empty;
    public string Phone { get; init; } = string.Empty;
}

