                           @onchange="e => UpdateReference(index, References[index] with { Name = (string?)e.Value ?? string.Empty })" />
                </div>
                <div class="form-group">
                    <label>Relationship *</label>
                    <input type="text" value="@References[index].Relationship"
                           @onchange="e => UpdateReference(index, References[index] with { Relationship = (string?)e.Value ?? string.Empty })" />
                </div>
            </div>

            <div class="form-row">
                <div class="form-group">
                    <label>Email *</label>
                    <input type="email" value="@References[index].Email"
                           @onchange="e => UpdateReference(index, References[index] with { Email = (string?)e.Value ?? string.Empty })" />
                </div>
                <div class="form-group">
                    <label>Phone *</label>
                    <input type="tel" value="@References[index].Phone"
                           @onchange="e => UpdateReference(index, References[index] with { Phone = (string?)e.Value ?? string.Empty })" />
                </div>
            </div>

            @if (References.Count > 2)
            {
                <button type="button" class="btn-remove" @onclick="() => RemoveReference(index)">Remove</button>
            }
