@namespace sv_1a7723c480004a659df359a368aa36e1.Components.Pages.Apply

<div class="step-content">
    <h2>References</h2>

    @if (!string.IsNullOrEmpty(ErrorMessage))
    {
        <div class="error-message">@ErrorMessage</div>
    }

    @for (int i = 0; i < References.Count; i++)
    {
        var index = i;
        <fieldset class="reference-fieldset">
            <legend>Reference @(index + 1)</legend>

            <div class="form-row">
                <div class="form-group">
                    <label>Name *</label>
                    <input type="text" value="@References[index].Name"
                           @onchange="e => UpdateReference(index, References[index] with { Name = (string?)e.Value ?? string.Empty })" />
                </div>
                <div class="form-group">
                    <label>Relationship *</label>
                    <input type="text" value="@References[index].Relationship"
                           @onchange="e => UpdateReference(index, References[index] with { Relationship = (string?)e.Value ?? string.Empty })" />
                </div>
            </div>

            <div class="form-row">
                <div class="form-group">
                    <label>Email *</label>
                    <input type="email" value="@References[index].Email"
                           @onchange="e => UpdateReference(index, References[index] with { Email = (string?)e.Value ?? string.Empty })" />
                </div>
                <div class="form-group">
                    <label>Phone *</label>
                    <input type="tel" value="@References[index].Phone"
                           @onchange="e => UpdateReference(index, References[index] with { Phone = (string?)e.Value ?? string.Empty })" />
                </div>
            </div>

            @if (References.Count > 2)
            {
                <button type="button" class="btn-remove" @onclick="() => RemoveReference(index)">Remove</button>
            }
        </fieldset>
    }

    @if (References.Count < 3)
    {
        <button type="button" class="btn-secondary" @onclick="AddReference">+ Add Reference</button>
    }

    <div class="step-actions">
        <button type="button" class="btn-outline" @onclick="OnBack">Back</button>
        <button type="button" class="btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

<style>
    .reference-fieldset {
        border: 1px solid #e5e7eb;
        border-radius: 0.5rem;
        padding: 1rem;
        margin-bottom: 1rem;
    }

    .reference-fieldset legend {
        font-weight: 600;
        padding: 0 0.5rem;
    }
</style>

@code {
    [Parameter] public List<ReferenceModel> References { get; set; } = new() { new(), new() };
    [Parameter, EditorRequired] public EventCallback<List<ReferenceModel>> OnNext { get; set; }
    [Parameter, EditorRequired] public EventCallback OnBack { get; set; }

    private string? ErrorMessage;

    private void AddReference()
    {
        if (References.Count < 3)
            References.Add(new ReferenceModel());
    }

    private void RemoveReference(int index)
    {
        if (References.Count > 2)
            References.RemoveAt(index);
    }

    private void UpdateReference(int index, ReferenceModel updated)
    {
        References[index] = updated;
    }

    private async Task HandleNext()
    {
        ErrorMessage = null;

        foreach (var r in References)
        {
            if (string.IsNullOrWhiteSpace(r.Name) || string.IsNullOrWhiteSpace(r.Relationship)
                || string.IsNullOrWhiteSpace(r.Email) || string.IsNullOrWhiteSpace(r.Phone))
            {
                ErrorMessage = "All reference fields are required.";
                return;
            }
        }

        await OnNext.InvokeAsync(References);
    }
}

