@page "/apply"
@rendermode InteractiveServer
@using sv_1a7723c480004a659df359a368aa36e1.Components.Pages.Apply
@using sv_1a7723c480004a659df359a368aa36e1.Models

<PageTitle>Job Application</PageTitle>

<div class="apply-container">
    <h1>Job Application</h1>

    <StepIndicator CurrentStep="@currentStep"
                   CompletedSteps="@completedSteps"
                   OnStepSelected="GoToStep" />

    @switch (currentStep)
    {
        case 0:
            <PersonalInfoStep FullName="@fullName"
                              Email="@email"
                              Phone="@phone"
                              Address="@address"
                              OnNext="HandlePersonalInfoNext" />
            break;

        case 1:
            <WorkHistoryStep Entries="@workEntries"
                             OnNext="HandleWorkHistoryNext"
                             OnBack="GoBack" />
            break;

        case 2:
            <ReferencesStep References="@references"
                            OnNext="HandleReferencesNext"
                            OnBack="GoBack" />
            break;

        case 3:
            <CoverLetterStep CoverLetter="@coverLetter"
                             OnNext="HandleCoverLetterNext"
                             OnBack="GoBack" />
            break;

        case 4:
            <ReviewStep FullName="@fullName"
                        Email="@email"
                        Phone="@phone"
                        Address="@address"
                        WorkEntries="@workEntries"
                        References="@references"
                        CoverLetter="@coverLetter"
                        IsSubmitting="@isSubmitting"
                        IsSubmitted="@isSubmitted"
                        ApplicationId="@applicationId"
                        ErrorMessage="@submitError"
                        OnEditStep="GoToStep"
                        OnBack="GoBack"
                        OnSubmit="HandleSubmit" />
            break;
    }
</div>

<style>
    .apply-container {
        max-width: 48rem;
        margin: 2rem auto;
        padding: 0 1rem;
    }

    .apply-container h1 {
        text-align: center;
        margin-bottom: 1.5rem;
    }

    .form-group {
        margin-bottom: 1rem;
    }

    .form-group label {
        display: block;
        font-weight: 600;
        margin-bottom: 0.25rem;
        font-size: 0.875rem;
    }

    .form-group input,
    .form-group textarea {
        width: 100%;
        padding: 0.5rem;
        border: 1px solid #d1d5db;
        border-radius: 0.375rem;
        font-size: 0.9rem;
    }

    .form-row {
        display: grid;
        grid-template-columns: 1fr 1fr;
        gap: 1rem;
    }

    .step-content {
        min-height: 20rem;
    }

    .step-actions {
        display: flex;
        justify-content: space-between;
        margin-top: 1.5rem;
        padding-top: 1rem;
        border-top: 1px solid #e5e7eb;
    }

    .btn-primary {
        background-color: #2563eb;
        color: white;
        border: none;
        padding: 0.6rem 1.5rem;
        border-radius: 0.375rem;
        font-size: 0.9rem;
        cursor: pointer;
    }

    .btn-primary:hover {
        background-color: #1d4ed8;
    }

    .btn-primary:disabled {
        background-color: #93c5fd;
        cursor: not-allowed;
    }

    .btn-outline {
        background: white;
        color: #374151;
        border: 1px solid #d1d5db;
        padding: 0.6rem 1.5rem;
        border-radius: 0.375rem;
        font-size: 0.9rem;
        cursor: pointer;
    }

    .btn-outline:hover {
        background-color: #f9fafb;
    }

    .btn-secondary {
        background: #f3f4f6;
        color: #374151;
        border: 1px solid #d1d5db;
        padding: 0.5rem 1rem;
        border-radius: 0.375rem;
        font-size: 0.85rem;
        cursor: pointer;
        margin-top: 0.5rem;
    }

    .btn-secondary:hover {
        background-color: #e5e7eb;
    }

    .error-message {
        background-color: #fef2f2;
        border: 1px solid #fecaca;
        color: #dc2626;
        padding: 0.75rem;
        border-radius: 0.375rem;
        margin-bottom: 1rem;
        font-size: 0.875rem;
    }

    .field-error {
        color: #dc2626;
        font-size: 0.8rem;
        margin-top: 0.25rem;
    }
</style>

@code {
    [Inject] private IApplicationService ApplicationService { get; set; } = default!;

    private int currentStep;
    private HashSet<int> completedSteps = new();

    // Step 1 state
    private string fullName = string.Empty;
    private string email = string.Empty;
    private string phone = string.Empty;
    private string address = string.Empty;

    // Step 2 state
    private List<WorkEntryModel> workEntries = new() { new WorkEntryModel() };

    // Step 3 state
    private List<ReferenceModel> references = new() { new(), new() };

    // Step 4 state
    private string coverLetter = string.Empty;

    // Step 5 state
    private bool isSubmitting;
    private bool isSubmitted;
    private int applicationId;
    private string? submitError;

    private void GoToStep(int step)
    {
        currentStep = step;
    }

    private void GoBack()
    {
        if (currentStep > 0)
            currentStep--;
    }

    private void HandlePersonalInfoNext(PersonalInfoStep.PersonalInfoResult result)
    {
        fullName = result.FullName;
        email = result.Email;
        phone = result.Phone;
        address = result.Address;
        completedSteps.Add(0);
        currentStep = 1;
    }

    private void HandleWorkHistoryNext(List<WorkEntryModel> entries)
    {
        workEntries = entries;
        completedSteps.Add(1);
        currentStep = 2;
    }

    private void HandleReferencesNext(List<ReferenceModel> refs)
    {
        references = refs;
        completedSteps.Add(2);
        currentStep = 3;
    }

    private void HandleCoverLetterNext(string letter)
    {
        coverLetter = letter;
        completedSteps.Add(3);
        currentStep = 4;
    }

    private async Task HandleSubmit()
    {
        isSubmitting = true;
        submitError = null;

        try
        {
            var workHistory = new WorkHistory(workEntries.Select(e =>
                new WorkEntry(e.Company, e.Title, e.StartDate, e.IsCurrent ? null : e.EndDate, e.Description)
            ).ToList());

            var refList = references.Select(r =>
                new Reference(r.Name, r.Relationship, r.Email, r.Phone)
            ).ToList();

            var personal = new PersonalInfo(fullName, email, phone, address);
            var application = new JobApplication(personal, workHistory, refList, coverLetter);

            applicationId = await ApplicationService.SubmitApplicationAsync(application);
            isSubmitted = true;
            completedSteps.Add(4);
        }
        catch (Exception ex)
        {
            submitError = $"Submission failed: {ex.Message}";
        }
        finally
        {
            isSubmitting = false;
        }
    }
}

